from collections import deque

def edmonds_karp(n={{n}}, cap={{capacity}}, s={{s}}, t={{t}}):
    flow = 0
    while True:
        parent = [-1]*n; parent[s] = s
        q = deque([s])
        while q and parent[t] == -1:
            u = q.popleft()
            for v in range(n):
                if parent[v] == -1 and cap[u][v] > 0:
                    parent[v] = u; q.append(v)
        if parent[t] == -1: break
        push = float('inf'); v = t
        while v != s:
            push = min(push, cap[parent[v]][v]); v = parent[v]
        v = t
        while v != s:
            cap[parent[v]][v] -= push; cap[v][parent[v]] += push; v = parent[v]
        flow += push
    return flow
